module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output reg [WIDTH-1:0]	rdata
);


wire wen, ren;
reg [($clog2(DEPTH))-1:0] waddr, raddr;
reg [($clog2(DEPTH))-1:0] waddr_bin, raddr_bin;
reg [($clog2(DEPTH))-1:0] wptr, rptr;
reg [($clog2(DEPTH))-1:0] wptr_buff, wptr_syn;
reg [($clog2(DEPTH))-1:0] rptr_buff, rptr_syn;
reg [3:0] wptr_gray, rptr_gray;
reg [3:0] wptr_buff_gray, wptr_syn_gray;
reg [3:0] rptr_buff_gray, rptr_syn_gray;

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
